package edu.pe.cibertec.saibm.libro.infrastructure.in.rest;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.HexFormat; import java.util.concurrent.ConcurrentHashMap; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import jakarta.servlet.http.HttpServletRequest; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component;
/** Temporary signed local boundary; replace with service-local JWT authorization. */ @Component public class TransitionalWriteAuthorizer { private final String secret; private final ConcurrentHashMap<String,Long> used=new ConcurrentHashMap<>(); public TransitionalWriteAuthorizer(@Value("${libro.security.transitional-secret:}")String s){secret=s;} public void require(HttpServletRequest r){String t=r.getHeader("X-SAIBM-Write-Timestamp"),n=r.getHeader("X-SAIBM-Write-Nonce"),sig=r.getHeader("X-SAIBM-Write-Signature");if(secret.isBlank()||t==null||n==null||sig==null)throw new WriteAuthorizationException();try{long ts=Long.parseLong(t);if(Math.abs(Instant.now().getEpochSecond()-ts)>60||!n.matches("[A-Fa-f0-9-]{20,}")||used.putIfAbsent(n,ts)!=null)throw new WriteAuthorizationException();String v=r.getMethod()+"\n"+r.getRequestURI()+"\n"+t+"\n"+n;if(!MessageDigest.isEqual(sign(v).getBytes(StandardCharsets.UTF_8),sig.getBytes(StandardCharsets.UTF_8)))throw new WriteAuthorizationException();}catch(NumberFormatException e){throw new WriteAuthorizationException();}} private String sign(String v){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(m.doFinal(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new WriteAuthorizationException();}} }
